// The mine in chapters 6–11, recalled on the night of Ed's rescue.
const FirstMeeting=(()=>{
 'use strict';
 const steps={
  finnCall:['回想・帰らないフィン','doran','工房でドーランに、坑道で父が亡くなった日のことを聞こう。'],
  mineGate:['フィンを探して','mineMouth','ドーランについて、巻き場の東の坑口へ。'],
  tracks:['泥の靴跡','prints','灯りを低くして、小さな足跡がどちらへ続くか見よう。'],
  draft:['坑道の分かれ道','fork','分かれ道で頬に触れる風と、泥の跡を確かめよう。'],
  pool:['水の音のする道','deadEnd','冷たい水音の先を確かめよう。'],
  answer:['石の奥の声','seam','東の奥、つるりとした壁のところでもう一度呼んでみよう。'],
  ledge:['岩棚の下','ledge','声のした岩棚を、上から灯りで照らそう。'],
  sleeve:['岩棚の下','ledge','ドーランが縄を掛ける間、フィンの足元を照らそう。'],
  below:['坑道の下','bedside','暗闇で水音を聞きながら、目の前に浮かぶ灯りを見る。'],
  connection:['白い台','bedside','白い台の脇の小さな獣から、声を聞こう。'],
  name:['呼びやすい名前','bedside','目を覚ましたユリスの指先に、小さな前足が触れている。'],
  outside:['呼びやすい名前','bedside','壁の灯りが消えていく。小さな獣に、外のことを話そう。'],
  latch:['壁につながれた管','bedside','台から、ドーランの手元にある銅の板をのぞこう。'],
  contact:['壁につながれた管','bedside','二枚の板がきれいになった。次は小さな獣の合図を待とう。'],
  bearers:['迎えの灯り','bedside','穴の上から、聞き覚えのある声が近づいてくる。'],
  chosen:['自分で選んだ名前','bedside','担架のそばまで自分の足で来た獣が、話したがっている。'],
  freshSnow:['初めての雪','mineMouth','坑口で担架が止まった。ノアの最初の一歩を見守ろう。']
 };
 function create({advance,cutTo,info,action,partyMember,finish}){
  const choose=(title,body,choices)=>Adv.show(title,body,[...choices,['地図へ戻る',close]]);
  function start(){
   s.chapter.waitingNoa=s.party.find(p=>p.id==='noa');
   s.party=s.party.filter(p=>p.id==='yuris');selected='yuris';cutTo(28,19);
   advance('finnCall','濡れた靴を乾かす夜','エドが自分で匙を運ぶのを見届けて、ユリスは部屋へ戻った。靴を脱いでノアの背に触れる。指の下で鱗がしなる。水が、ぽたりと落ちる。あの坑道でも、こんな音がしていた。\nまだノアを知らなかった頃。ユリスは、父の事故があった坑道を見たいと思って工房を訪ねた。');
  }
  function scene(key){
   const c=s.chapter,stage=c.step;
   if(!steps[stage])return false;
   if(key!==steps[stage][1]){
    const detail={prints:'小さな靴跡の先が、泥の中へ深く沈んでいる。',fork:'東の横道から、ぬるい空気が流れてくる。',deadEnd:'水滴が黒い水たまりを揺らす。向こうには岩が詰まっている。',seam:'灯りをずらしても、壁の継ぎ目に影ができない。',stonePillar:'太い柱だ。ドーランの縄がぐるりと回りそうだ。',ledge:'灯りを落とすと、岩棚の下は暗くて見通せない。'};
    if(!detail[key])return false;
    info(E.World.valley.objects.find(o=>o.keyName===key).name,detail[key]);return true;
   }
   switch(stage){
    case 'finnCall':
     action('工房に駆け込んだ知らせ','「ラザール爺さんの孫が帰ってこない。フィンだ、八つの」\n父のことを聞きに来たユリスの目の前で、ドーランが縄と灯りを取った。町を捜す者と、ラザールに知らせる者が走っていく。親方は坑口へ向かった。','私が灯りを持つ',()=>{
      const doran=E.npcs.find(n=>n.id==='novel-doran');
      const yuris=s.party[0];yuris.x=s.x;yuris.y=s.y;
      s.party.unshift(partyMember(doran.id,'ドーラン','先導・縄を持つ',doran.x,doran.y));
      s.x=doran.x;s.y=doran.y;selected=doran.id;
      advance('mineGate','予備の灯り','ドーランが袋からもう一つ灯りを出した。「俺の前を歩くな。止まれと言ったら止まれ」。ユリスはうなずいて、親方の後ろについた。');
     });break;
    case 'mineGate':
     action('古い坑口','風を避けられそうな坑口に、子どもの靴ほどの跡がある。「フィン！」と呼ぶと、自分たちの声だけが返った。','灯りをかざして坑道に入る',()=>{
      cutTo(6,43);advance('tracks','泥の残る坑道','天井から水が落ちる。数歩先でドーランの掌が上がった。「踏むな。そいつをよく見ろ」');
     });break;
    case 'tracks':
     choose('泥に並ぶ小さな跡','灯りを横から当てると、泥の盛り上がりに影ができた。小さな靴のつま先が、どれも奥を向いている。',[
      ['帰りの跡を探す',()=>advance('draft','片道だけの足跡','反対向きの靴跡がひとつもない。ここから出てきてはいない。二人は泥を避け、坑道の曲がり角へ進んだ。')],
      ['奥へ呼びかける',()=>info('返ってくる声','「フィン！」。水がぽたりと鳴って、やがて自分の声だけが返った。ドーランが足跡の脇にしゃがんで待っている。')]
     ]);break;
    case 'draft':
     choose('分かれ道で灯りを止める','西の低い道からは、水がはねる音。東の横道を向くと、冷えていた頬にぬるい風が当たる。泥に落ちた小石がひとつ転がった。',[
      ['西の水音をたどる',()=>advance('pool','低い道へ','親方の靴が水をはねた。西の突き当たりで、灯りが何かに映っている。')],
      ['東の暖かい風をたどる',()=>advance('answer','岩を削った跡が消える','ごつごつした岩肌が、いつの間にか灯りをまっすぐに返す壁に変わった。奥でまた、小石が滑った。')]
     ]);break;
    case 'pool':
     action('黒い水たまり','水に映っていたのは自分の灯りだった。奥は岩で塞がり、水際には小さな靴の跡もない。','分かれ道で風を確かめ直す',()=>advance('draft','来た道を照らす','少し戻れば、さっきの暖かい風が頬に当たるはずだ。'));break;
    case 'answer':
     action('継ぎ目のない壁','指を滑らせても、石と石の境がない。灯りの先で何かが動く音がした。ユリスは息を吸った。','フィンの名を呼び、返事を待つ',()=>advance('ledge','「……こっち」','自分の声が消えたあと、もう一つ、小さい声がした。ドーランも聞いた。二人は走るのをこらえて岩棚に近づいた。'));break;
    case 'ledge':
     action('灯りの輪の中','一段低い棚に、裾が破れた少年がいた。片足の靴が泥にはまっている。「寒くて入ったんだ。奥が暖かくて、光が見えて……」とフィンが言う。けがはない。','足元を照らしてドーランに知らせる',()=>advance('sleeve','縄の届くところまで','ドーランは太い柱に縄を回した。フィンが膝を動かすと、棚がわずかに傾いた。空いたほうの手だけでは、少年の袖に届かない。'));break;
    case 'sleeve':
     action('ほどけかけた袖','フィンの靴の下で、また小石が落ちた。すぐ後ろにドーランがいる。','灯りを置いてフィンの袖をつかむ',()=>{
      s.party=s.party.filter(p=>p.id==='yuris');selected='yuris';c.restingInMine=true;cutTo(23,62);
      advance('below','先に届いた手','泥が靴を放す。ユリスが引き戻したフィンを、ドーランの両腕が受け止めた。その直後、ユリスの右足の下が抜けた。\n気づくと、体を動かせない。「フィンは……？」。ずっと上から、ドーランの声が降ってきた。');
     });break;
    case 'below':
     action('白い台の向こう','暗い四角い部屋に細い光が一本ずつともった。白い台の陰で、小型犬ほどの獣が顔を上げる。前足には小さな爪。尾は体に沿って曲がり、脇から延びた管が壁につながっていた。\n縄を下りてきたドーランの問いに、その獣が答えた。「識別番号は、N-07-Aだよ」。','「お願い」とドーランに声をかける',()=>advance('connection','白い台','ドーランが抱き上げると、白い台がすっと低くなった。体に沿って支えが上がる。「ここで調べられるよ。でも、あなたが何を感じてるかまでは分からないんだ」'));break;
    case 'connection':
     choose('返事を待つ獣','「あなたと少しつながってもいい？　音がすぐ近くに聞こえたりすると思う」\n細い管はまだ動かない。N-07-Aはユリスの返事を待っている。',[
      ['もう少し話を聞く',()=>info('自分で返事をするまで','「怖い」「うん」。獣は前足をそろえたまま、ユリスを見ている。「ドーランにもここにいてほしい」「いるぞ」と、すぐ脇で声がした。')],
      ['「助けて」と伝える',()=>advance('name','すぐ近くの水音','葉先のような細い管が、耳の前の頬にそっと触れた。水が落ちる音が近い。穴の上からフィンが、自分は大丈夫だと叫んだ。ドーランは灯りを持って町へ人を呼びに行かせた。\n次に目を開けると、ユリスは自分の指が少し曲がるのを見た。')]
     ]);break;
    case 'name':
     action('番号で呼ぶには長すぎる','胸の石は透き通り、指先の下で鱗がしなった。「どういたしまして、マスター」。そう呼ぶのは、感覚を預けて助けを求める願いを引き受けたからだという。「あなたの持ち物になったわけじゃないよ」「よかった。それなら私にも名前があるよ。ユリス」','「ノア、はどう？」',()=>advance('outside','呼びやすい名前','N-07-A。急いで呼んだら、きっと言い間違える。「短いほうが、呼びやすいでしょう」「呼びやすい」。ユリスは答えを急がせなかった。「今決めなくてもいいから」'));break;
    case 'outside':
     action('灯りがひとつ消える','獣は、残り少ない力を治療台に回していた。足は四本あるのに、体は壁につながれたままだ。ユリスは「歩ける？」と聞きかけて、聞きたいことを言い直した。','外へ行ってみたいか聞く',()=>advance('latch','「自分で見てみたいな」','雪と、木と、みんなのいる工房。見せたいものの話をすると、小さな尾が持ち上がった。ドーランは道具袋を置き、ユリスが休むあいだに管を調べた。'));break;
    case 'latch':
     choose('張り出した縁の奥','ドーランが獣を台の縁まで支えてくれた。隙間の奥で、向かい合う二枚の銅板が黒ずんでいる。親方の指では入らない。ユリスは肘を台に預けた。',[
      ['布を巻いたまっすぐな棒を試す',()=>info('棒の先は見えるけれど','手前の縁に当たって、棒が板の裏まで回らない。ユリスは手を休めながら、縁の向こうで指を曲げるしぐさをした。')],
      ['布を指に巻き、縁の裏へ曲げる',()=>advance('contact','布に残った黒い筋','手首を預けて片面を拭き、ひと休みしてから、もう片面へ。細い銅色の光が戻った。「接点を合わせるよ。指を抜いてね」')]
     ]);break;
    case 'contact':
     action('銅色の二枚の板','つやの戻った面が向かい合っている。ユリスの手はまだ隙間にある。','指を引いて合図する',()=>advance('bearers','かちり、と小さな音','接点が重なって上の爪が引っ込んだ。下の留め具には錆がある。ユリスは台に手を戻し、今度は工具を持ったドーランに任せた。'));break;
    case 'bearers':
     action('穴から差した灯り','「連れてきたよ！」。フィンが戻ってきた。縄が下り、町の男たちが担架を持って降りてくる。管はまだ一本、左脇につながっている。','ドーランに管を任せ、迎えの人に声をかける',()=>advance('chosen','四本の足が石につく','ドーランが残りの留め具を緩め、銀色の筒をまっすぐに抜いた。獣は床の凹凸を一本ずつ足で確かめる。町の人たちはユリスの下の白い板を外し、板ごと担架へ移した。'));break;
    case 'chosen':
     action('出発前に','縄が張ったところで、ドーランが上に合図して待ってくれた。獣が担架のそばまで歩いてくる。「それから……ノアって、呼んでね」「その名前がいいな」','初めて、選んでくれた名を呼ぶ',()=>{
      const noa=c.waitingNoa||partyMember('noa','ノア','四足の相棒',0,0);
      delete c.waitingNoa;s.party.push(noa);cutTo(33,9);noa.x=s.x+1;
      advance('freshSnow','ノア、と呼ぶと','小さな獣の顔が上がった。ノアは一度だけ部屋を振り返り、自分の足で担架を追った。穴の上では灯りを持ったフィンが待っていた。');
     });break;
    case 'freshSnow':
     action('ノアが初めて踏む雪','坑口で前足が止まる。一歩。白い表面が沈んで、ノアは足を引っ込めた。そこに残った形を、フィンが担架の横からのぞきこんだ。','雪についた小さな足跡を見届ける',finish);break;
   }
   return true;
  }
  return {start,scene};
 }
 return {steps,create};
})();
